import sys; sys.path.insert(0,'source')
from Pynite import FEModel3D
def portal():
    m=FEModel3D(); m.add_material('steel',29000,11200,0.3,0.284); m.add_section('S',10,100,150,250)
    for n,x in (('a',0),('b',10),('c',20)):
        m.add_node(n,x,0,0); m.add_node(n+'t',x,10,0)
    for n in ('a','b','c'): m.add_member('col'+n,n,n+'t','steel','S')
    m.add_member('b1','at','bt','steel','S'); m.add_member('b2','bt','ct','steel','S')
    for n in ('a','b','c'): m.def_support(n,1,1,1,1,1,1)
    m.add_node_load('bt','FX',5); return m
vals={}
for sp in (True,False):
    m=portal(); m.analyze(sparse=sp, check_statics=False)
    vals[sp]=float(m.nodes['bt'].DX['Combo 1'])
ds=abs(vals[True]-vals[False]); rel=ds/abs(vals[True])
print(f'sparse DX={vals[True]"'!r}'"')
print(f'dense  DX={vals[False]"'!r}'"')
print(f'abs diff={ds:.3e}  relative diff={rel:.3e}  (machine eps={2**-52:.3e})')
print(f'agree to 1e-9 relative: {rel < 1e-9}')
\""
